mapper.select:
SELECT COUNT(*)
FROM MEMBER m



		AND m.STATUS = #{status}


		AND m.ROLE_ID = #{roleId}

SELECT m.MEMBER_ID AS memberId, m.LOGIN_ID AS loginId, m.NAME AS name, m.EMAIL AS email, m.PHONE AS phone, TO_CHAR(m.BIRTH, 'YYYY-MM-DD') AS birth, m.STATUS AS status, TO_CHAR(m.CREATED_AT, 'YYYY-MM-DD') AS createdAt, r.ROLE_NAME AS roleName, m.SNS_PROVIDER AS snsProvider FROM MEMBER m JOIN APP_ROLE r ON m.ROLE_ID = r.ROLE_ID
AND m.STATUS = #{status}
AND m.ROLE_ID = #{roleId}
ORDER BY m.CREATED_AT DESC OFFSET #{offset} ROWS FETCH FIRST #{size} ROWS ONLY

mapper.insert:
INSERT INTO MEMBER_STATUS_HIST(
			STATUS_HIST_ID, MEMBER_ID, ADMIN_ID, BEFORE_STATUS, AFTER_STATUS, REASON, START_AT
) VALUES (
	SEQ_MEMBER_STATUS_HIST.NEXTVAL, #{memberId}, #{adminId}, #{beforeStatus}, #{afterStatus}, #{reason}, SYSTIMESTAMP
)
